package unionfind;

import java.util.Arrays;
import java.util.Objects;

public final class UnionFind {
    private final int[] parent;
    private int componentCount;

    public UnionFind(int size) {
        if (size < 0) {
            throw new IllegalArgumentException("size must be non-negative");
        }

        parent = new int[size];
        componentCount = size;
        Arrays.fill(parent, -1);
    }

    public int find(int element) {
        Objects.checkIndex(element, parent.length);

        int root = element;
        while (parent[root] >= 0) {
            root = parent[root];
        }

        while (element != root) {
            int next = parent[element];
            parent[element] = root;
            element = next;
        }

        return root;
    }

    public boolean union(int first, int second) {
        int rootFirst = find(first);
        int rootSecond = find(second);

        if (rootFirst == rootSecond) {
            return false;
        }

        if (componentSize(rootFirst) < componentSize(rootSecond)) {
            mergeRoots(rootFirst, rootSecond);
        } else {
            mergeRoots(rootSecond, rootFirst);
        }

        componentCount--;
        return true;
    }

    public boolean connected(int first, int second) {
        return find(first) == find(second);
    }

    public int componentCount() {
        return componentCount;
    }

    public int elementCount() {
        return parent.length;
    }

    private int componentSize(int root) {
        return -parent[root];
    }

    private void mergeRoots(int childRoot, int parentRoot) {
        parent[parentRoot] += parent[childRoot];
        parent[childRoot] = parentRoot;
    }
}

package unionfind;

final class TestSupport {
    private TestSupport() {
    }

    static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    static void assertFalse(boolean condition, String message) {
        if (condition) {
            throw new AssertionError(message);
        }
    }

    static void assertEquals(int expected, int actual, String message) {
        if (expected != actual) {
            throw new AssertionError(message + " (expected " + expected + ", got " + actual + ")");
        }
    }

    static void assertThrows(Class<? extends Throwable> expectedType, ThrowingRunnable action) {
        try {
            action.run();
        } catch (Throwable thrown) {
            if (expectedType.isInstance(thrown)) {
                return;
            }

            throw new AssertionError(
                    "expected " + expectedType.getSimpleName() + " but got " + thrown.getClass().getSimpleName(),
                    thrown);
        }

        throw new AssertionError("expected " + expectedType.getSimpleName() + " to be thrown");
    }

    @FunctionalInterface
    interface ThrowingRunnable {
        void run() throws Throwable;
    }
}

